package com.terrassic.research;

/**
 * Field Journal objectives of Chapter 1 (docs/HISTORIA.md, section 5, and docs/CONQUISTAS.md): 4 themes with 3
 * objectives each; 2 of 3 complete a theme, and a complete theme is one amber fragment. Each objective and each
 * fragment is also a vanilla advancement (data/terrassic/advancements/chapter1/, criterion "done", generated by
 * tools/javagen/conquistas.py). Objectives whose feature is not in the game yet are listed with their hint but
 * cannot be completed and have no advancement.
 */
public enum Objective {
    SHELTER(Theme.SURVIVAL, true),
    FIRST_SPEAR(Theme.SURVIVAL, true),
    RIFT_STORM(Theme.SURVIVAL, false),
    STUDY_FIVE(Theme.SCIENCE, true),
    FIRST_FOSSIL(Theme.SCIENCE, true),
    RESEARCH_TABLE(Theme.SCIENCE, true),
    TAME_HERBIVORE(Theme.TAMING, true),
    HATCH_EGG(Theme.TAMING, true),
    RIDE(Theme.TAMING, true),
    KATARINA_PAGES(Theme.EXPLORATION, true),
    INLAND_SEA(Theme.EXPLORATION, true),
    MIGRATION(Theme.EXPLORATION, false);

    public enum Theme {
        SURVIVAL, SCIENCE, TAMING, EXPLORATION;

        public String id() {
            return this.name().toLowerCase(java.util.Locale.ROOT);
        }

        /** The fragment advancement of this theme. */
        public String advancement() {
            return "chapter1/fragment_" + this.id();
        }
    }

    /** Thatch blocks to place for {@link #SHELTER}. */
    public static final int SHELTER_BLOCKS = 16;
    /** Studied species for {@link #STUDY_FIVE}. */
    public static final int STUDY_SPECIES = 5;
    /** Katarina pages for {@link #KATARINA_PAGES}. */
    public static final int PAGES = 3;
    /** Objectives of a theme needed to complete it. */
    public static final int PER_THEME = 2;

    private final Theme theme;
    private final boolean available;

    Objective(Theme theme, boolean available) {
        this.theme = theme;
        this.available = available;
    }

    public String id() {
        return this.name().toLowerCase(java.util.Locale.ROOT);
    }

    public Theme theme() {
        return this.theme;
    }

    /** false = the feature it needs is not in the game yet. */
    public boolean available() {
        return this.available;
    }

    public String advancement() {
        return "chapter1/" + this.id();
    }

    /** Objectives of a theme the player has done. */
    public static int done(Knowledge k, Theme theme) {
        int n = 0;
        for (Objective o : values()) {
            if (o.theme == theme && k.hasObjective(o)) {
                n++;
            }
        }
        return n;
    }

    /** Amber fragments: themes with {@link #PER_THEME} objectives done. The Leap Altar reads this number. */
    public static int fragments(Knowledge k) {
        int n = 0;
        for (Theme t : Theme.values()) {
            if (done(k, t) >= PER_THEME) {
                n++;
            }
        }
        return n;
    }
}
